"""Merge defaults < file < environment < explicit overrides."""
import copy

def merge_config(defaults, file_values=None, env=None, overrides=None):
    result = copy.deepcopy(defaults)
    allowed = set(defaults)
    for layer in (file_values, env, overrides):
        if layer is None:
            continue
        unknown = set(layer) - allowed
        if unknown:
            raise ValueError("unknown configuration keys: " + ", ".join(sorted(unknown)))
        result.update(copy.deepcopy(layer))
    return result
